with w as(select*from public.works where id in(3283,4981,5028,5036,5766,5834,5986,5998,6030,6157,6169,6182,1403,1628,1844,2328,2332,3492,3496,3548,3559,5026,5046,5801,5853,5882,5898,5902,5905,5914,5944,5949,5965,5974,6000,6018,6027,6041,6056,6059,6061,6063,6078,6089,6119,6155,6197,6221,6230,6240,6249,6288,6293,6344,1355,2037,2312,2317,2355,2364)) select jsonb_build_object('checked_at',clock_timestamp(),'project','qvplwejffhjvxaypmjut','works',(select jsonb_agg(to_jsonb(w)order by id)from w),'authors',(select jsonb_agg(to_jsonb(a)order by id)from public.authors a where id in(select author_id from w)),'editions',(select jsonb_agg(to_jsonb(e)order by id)from public.editions e where work_id in(select id from w)),'metadata',(select coalesce(jsonb_agg(to_jsonb(m)order by edition_id),'[]')from public.catalog_edition_metadata m where work_id in(select id from w)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(d)order by work_id,language),'[]')from public.catalog_work_descriptions d where work_id in(select id from w)))as readback;